'use strict';
// City growth test 0.4: transport goals, shared infrastructure and optional operations.
TYPES.emu={name:'动车',short:'动',speed:52,cap:18,transfer:3,vehicle:560,line:0,icon:'▥',fare:1.4};
TYPES.bus.fare=1;TYPES.rail.fare=1.8;TYPES.air.fare=3;
const SHAPES=['●','▲','◆','■'],COLOR_NAMES=['蓝色','金色','紫色'];
function isTrain(t){return t==='emu'||t==='rail';}
const oldFresh=fresh;fresh=function(){let x=oldFresh();x.economyVersion=4;x.inventory.emu=0;x.limits={bus:6,emu:0,rail:0,air:0};x.infrastructure={};x.event=null;x.eventCooldown=0;x.eventArchive=[];x.contract=null;x.contractCooldown=0;x.lastDaily=0;x.ledger.events=0;x.ledger.contracts=0;return x;};
const oldMakeCity=makeCity;makeCity=function(...args){let c=oldMakeCity(...args);c.mission={step:0,progress:0,completed:0,in:0,out:0,records:[],streak:0,reached:[],since:S.day};c.today={in:0,out:0,good:0,total:0};return c;};
save=function(){try{localStorage.setItem('transit-atlas-city-beta-v2',JSON.stringify(S));}catch{}};
load=function(){try{let x=JSON.parse(localStorage.getItem('transit-atlas-city-beta-v2'));if(x&&x.version===1&&x.economyVersion===4){S=x;S.paused=true;return true;}}catch{}return false;};
function matchesDestination(c,p){return !c.dormant&&c.id!==p.origin&&(p.eventId?c.id===p.dest:c.color===p.color&&c.shape===p.shape);}
newPassenger=function(c){let choices=S.cities.filter(d=>d.id!==c.id&&!d.dormant&&(d.color!==c.color||d.shape!==c.shape));if(!choices.length)return;let weights=choices.map(d=>Math.pow(1.45,d.stage??d.size)*(c.shape===0?(d.shape===2||d.shape===3?2.6:1):d.shape===1?1.9:d.shape===2?1.4:1));let roll=Math.random()*weights.reduce((a,b)=>a+b,0),d=choices[0];for(let i=0;i<choices.length;i++){roll-=weights[i];if(roll<=0){d=choices[i];break;}}c.q.push({id:S.nextP++,origin:c.id,color:d.color,shape:d.shape,wait:0,ready:0,journey:0,legs:{}});};
key=function(a,b,type){return [isTrain(type)?'track':type,...[a.id,b.id].sort((x,y)=>x-y)].join('-');};
function infrastructure(a,b,type){return S.infrastructure[key(a,b,type)]||{a:a.id,b:b.id,type:isTrain(type)?'track':type,level:type==='rail'?2:0};}
edgeTime=function(a,b,type){let r=requirements(a,b,type),speed=TYPES[type].speed,infra=infrastructure(a,b,type);if(type==='bus')speed*=1+.15*infra.level;if(isTrain(type)&&infra.level<2)speed=Math.min(speed,52);if(infra.until>S.day)speed*=.7;return Math.hypot(a.x-b.x,a.y-b.y)/speed*(1+(r.hill||0)*.65);};
const oldCommit=commitDraft;commitDraft=function(skip=false){if(!draft)return;let proposed={...draft,stops:[...draft.stops]},built=Object.keys(S.corridors);oldCommit(skip);if(draft)return;for(let i=1;i<proposed.stops.length;i++){let a=S.cities[proposed.stops[i-1]],b=S.cities[proposed.stops[i]],k=key(a,b,proposed.type);if(!S.infrastructure[k])S.infrastructure[k]={a:a.id,b:b.id,type:isTrain(proposed.type)?'track':proposed.type,level:proposed.type==='rail'?2:proposed.type==='emu'?1:0};}save();};
function recordSegment(p,a,b,type){p.legs??={};let k=[a.id,b.id].sort((a,b)=>a-b).join('-');if(!p.legs[k])p.legs[k]={distance:Math.hypot(a.x-b.x,a.y-b.y),type};}
function tripFare(p,dest){let a=S.cities[p.origin];if(!a)return 0;let straight=Math.hypot(a.x-dest.x,a.y-dest.y),base=straight<250?1:straight<500?2:3,legs=Object.values(p.legs||{}),distance=legs.reduce((n,l)=>n+l.distance,0),weighted=legs.reduce((n,l)=>n+l.distance*(TYPES[l.type]?.fare||1),0);if(!distance)return base;return Math.max(.1,Math.round(base*weighted/distance*Math.min(1,straight*1.25/distance)*10)/10);}
function passengerLabel(p){return p.eventId?'♪ '+(p.returnTrip?'返程 → ':'演唱会 → ')+escapeHTML(S.cities[p.dest]?.name||'活动城市'):SHAPES[p.shape]+' '+COLOR_NAMES[p.color]+FEATURES[p.shape].name;}
function focusPassenger(kind,id,color,shape){if(kind==='event'){focusDestination(id);return;}selected={type:'demand',id:S.cities.find(c=>c.color===color&&c.shape===shape&&!c.dormant)?.id??0,color,shape};showDetails();toast('已标记 '+COLOR_NAMES[color]+SHAPES[shape]+' · 任意同色同形城市均可接收');}
completeTrip=function(p,dest){credit(tripFare(p,dest),'fares','交通票款');dest.arrivals++;let origin=S.cities[p.origin];if(origin)origin.departures++;let good=p.wait<=90*(S.cities[p.origin]?.shape===1?1.25:1);for(let [c,dir] of [[dest,'in'],[origin,'out']]){if(!c)continue;c.today[dir]++;c.today.total++;if(good)c.today.good++;if(!p.eventId)advanceMission(c,dir,p,good);}if(p.eventId){let ev=S.event;if(ev&&p.eventId===ev.id){if(p.returnTrip)ev.returned++;else{ev.attended++;ev.attendees.push({home:p.origin});credit(ev.share,'events','演唱会到场分成');}}}else{let contract=S.contract;if(contract&&S.day<=contract.end&&(dest.id===contract.city||origin?.id===contract.city)){contract.count++;if(good)contract.good++;}}};
function missionSpec(c){let step=c.mission.step,feature=FEATURES[c.shape];if(step>=6)return null;let configs=[{mode:'count',goal:20,reward:70,title:feature.verb,desc:feature.desc},{mode:'dual',goal:12,reward:130,title:'双向服务',desc:'本城出发与到达本城，各完成12人出行。'},{mode:'window',goal:18,reward:160,title:'限期高效运输',desc:'任意连续12天完成18人主方向运输，至少80%候车不超过90秒。'},{mode:'streak',goal:3,reward:220,title:'稳定运营',desc:'连续3个完整游戏日，每天至少完成1人主方向运输，且80%候车不超过90秒。'},{mode:'reach',goal:2,reward:240,title:'区域互通',desc:'本城居民实际到达两种不同的颜色＋形状类别，允许换乘。'},{mode:'streak',goal:5,reward:320,title:'城市群运输考核',desc:'连续5个完整游戏日，每天至少完成2人主方向运输，且80%候车不超过90秒。'}];return {...configs[step],upgrade:step===1||step===3,verb:configs[step].title};}
function missionDirection(c,dir){return c.shape===0?dir==='out':dir==='in';}
function advanceMission(c,dir='in',p={},good=true){let m=c.mission,spec=missionSpec(c);if(!spec||c.dormant)return;m.in??=0;m.out??=0;m.records??=[];m.reached??=[];if(dir==='in')m.in++;else m.out++;let main=missionDirection(c,dir);if(main){m.records.push({day:S.day,good});m.records=m.records.filter(x=>x.day>S.day-12);if(spec.mode==='count')m.progress++;if(spec.mode==='window')m.progress=m.records.length;}if(spec.mode==='dual')m.progress=Math.min(m.in,m.out);if(spec.mode==='reach'&&dir==='out'){let d=S.cities[p.actualDest];if(d){let category=d.color+'-'+d.shape;if(!m.reached.includes(category))m.reached.push(category);m.progress=m.reached.length;}}if(spec.mode==='streak'){m.dayTrips=(m.dayTrips||0)+(main?1:0);m.dayGood=(m.dayGood||0)+(main&&good?1:0);}let eligible=m.progress>=spec.goal;if(spec.mode==='window')eligible=eligible&&m.records.filter(x=>x.good).length/m.records.length>=.8;if(spec.mode!=='streak'&&eligible)finishMission(c);}
function finishMission(c){let spec=missionSpec(c);if(!spec)return;let old=c.mission;credit(spec.reward,'tasks',c.name+' · '+spec.title);c.mission={step:old.step+1,completed:old.completed+1,progress:0,in:0,out:0,records:[],reached:[],streak:0,since:S.day,dayTrips:0,dayGood:0};if(spec.upgrade&&c.size<2){c.size++;c.capacity=[24,40,64][c.size];credit(60,'tasks',c.name+'繁荣奖励');toast(c.name+'升级为'+LEVELS[c.size]+' · 奖励 ¥'+(spec.reward+60));}else toast(c.name+'完成 '+spec.title+' · +¥'+spec.reward);c.rewardUntil=S.day+1.5;updateUI();save();}
function missionHTML(c){let spec=missionSpec(c),m=c.mission;if(c.dormant)return '<div class="city-mission"><h4>待接入城镇</h4><p>拉线接通后开始产生客流，有45秒接入宽限。</p></div>';if(!spec)return '<div class="city-mission"><h4>城市群考核已完成</h4><p>继续服务客流、承接合同和举办活动。</p></div>';let detail=spec.mode==='dual'?`出发 ${m.out||0}/12 · 到达 ${m.in||0}/12`:spec.mode==='streak'?`连续 ${m.streak||0}/${spec.goal} 天 · 今日 ${m.dayTrips||0}/${m.step===5?2:1} 人`:spec.mode==='window'?`${m.records.filter(x=>x.day>S.day-12).length}/${spec.goal} 人 · 合格 ${Math.round(m.records.length?m.records.filter(x=>x.good).length/m.records.length*100:0)}%`:`${m.progress}/${spec.goal} ${spec.mode==='reach'?'类别':'人'}`;return `<div class="city-mission"><div class="mission-heading"><span class="eyebrow">阶段任务 ${m.step+1} / 6</span><b>+¥${spec.reward+(spec.upgrade?60:0)}</b></div><h4>${spec.title}</h4><p>${spec.desc}</p><div class="mission-progress"><i style="width:${Math.min(100,m.progress/spec.goal*100)}%"></i></div><div class="mission-heading"><span>${detail}</span><small>${spec.upgrade?'完成后升级扩容':'自动发奖'}</small></div><small>连续任务中断只重置连续天数，不扣钱、不降级。</small></div>`;}
const oldTrip=completeTrip;completeTrip=function(p,dest){p.actualDest=dest.id;oldTrip(p,dest);};
function completeDay(day){for(let c of S.cities){if(c.kind==='bridgehead')continue;let m=c.mission,spec=missionSpec(c);if(spec?.mode==='streak'&&!c.dormant){let completeDay=day-1>=Math.floor(m.since)+1,min=m.step===5?2:1;if(completeDay){let valid=(m.dayTrips||0)>=min&&(m.dayGood||0)/m.dayTrips>=.8;m.streak=valid?(m.streak||0)+1:0;m.progress=m.streak;if(m.streak>=spec.goal)finishMission(c);}}c.mission.dayTrips=0;c.mission.dayGood=0;c.today={in:0,out:0,total:0,good:0};}}
function checkUnlocks(){for(let [type,day,trips,minCities] of [['emu',25,60,0],['rail',65,250,3],['air',120,600,0]]){if(S.unlocked.includes(type)||S.day<day||S.delivered<trips||S.cities.filter(c=>c.size>=1).length<minCities)continue;S.unlocked.push(type);S.limits[type]=type==='air'?2:3;toast('已开放'+TYPES[type].name+' · 可在交通采购中购买');save();}}
reward=function(points){S.lastSettlement=S.day;toast('十天基础补助 +¥'+points);checkUnlocks();updateUI();save();};
function updateWorld(dt,oldDay){for(let infra of Object.values(S.infrastructure)){if(infra.until&&S.day>=infra.until){infra.level=infra.target;delete infra.until;delete infra.target;toast((infra.type==='bus'?'道路拓宽':'铁路改造')+'完工 · 速度已提升');}}if(Math.floor(S.day)>oldDay)completeDay(Math.floor(S.day));if(S.contract&&S.day>S.contract.end){let c=S.contract,ok=c.count>=c.goal&&c.good/Math.max(1,c.count)>=.8;if(ok)credit(c.reward,'contracts','公共服务合同');S.contract=null;S.contractCooldown=S.day+5;toast(ok?'服务合同达成 · +¥'+c.reward:'服务合同未达标 · 无扣款，5天后可重接');save();}checkUnlocks();updateConcert();}
function carPrice(v){return (v.type==='emu'?70:110)+Math.max(0,v.cars-2)*20;}
upgradeCar=function(id){let v=S.vehicles.find(v=>v.id===id);if(!v||!isTrain(v.type)||v.cars>=8)return;let price=carPrice(v);if(S.points<price)return toast('资金不足，需要 ¥'+price);spend(price,'vehicles','增加'+TYPES[v.type].name+'车厢');v.cars++;v.investment=(v.investment||0)+price;showDetails();save();};
function unlockText(t){if(t==='emu')return '第25天＋送达60人';if(t==='rail')return '第65天＋送达250人＋3座小城';if(t==='air')return '第120天＋送达600人';return '已开放';}
chooseType=function(){openModal(`<div class="modal-head"><h2>规划交通线路</h2><button class="close" onclick="closeModal()">×</button></div><p>拖动拉线，确认报价后建设。公交→动车→高铁→航空，逐步发展。</p><div class="fleet-grid">${['bus','emu','rail','air'].map(t=>`<button class="reward" onclick="beginDraft('${t}')" ${!S.unlocked.includes(t)||S.lines.filter(l=>l.type===t&&!l.retiring).length>=S.limits[t]?'disabled':''}>${transportIcon(t)}<b>${TYPES[t].name}</b><small>首辆 ¥${TYPES[t].vehicle}<br>${S.unlocked.includes(t)?'空余线路 '+(S.limits[t]-S.lines.filter(l=>l.type===t&&!l.retiring).length):unlockText(t)}</small></button>`).join('')}</div><p>动车普通铁路造价较低；高铁新建高速铁路。同一路段的普通铁路可逐步改造，动车也可使用高速铁路。</p>`);};
shop=function(){openModal(`<div class="modal-head"><div><span class="eyebrow">TRANSPORT DEPOT / 0.4</span><h2>交通采购</h2></div><div><b>¥${S.points}</b><button class="close" onclick="closeModal()">×</button></div></div><div class="fleet-grid">${['bus','emu','rail','air'].map(t=>`<div class="product">${transportIcon(t)}<b>${TYPES[t].name}</b><small>${isTrain(t)?'初始2节，最多8节':TYPES[t].cap+'人'} · 票价 ×${TYPES[t].fare}<br>${S.unlocked.includes(t)?'库存 '+S.inventory[t]:unlockText(t)}</small><button onclick="purchase('v-${t}')" ${!S.unlocked.includes(t)||S.points<TYPES[t].vehicle?'disabled':''}>¥${TYPES[t].vehicle}　购买</button></div>`).join('')}</div><p>道路拓宽和铁路改造：点击线路→路段升级。施工期间速度−30%。<br>已购车辆可回收调配；道路月底收取维护费，桥梁独立建造。</p><button class="secondary" onclick="showFinance()">收支账本</button> <button class="secondary" onclick="showOperations()">运营中心</button>`);};
const oldDetails=showDetails;showDetails=function(rebuild=true){oldDetails(rebuild);if(selected?.type==='line'){let id=selected.id;if(!$('details').innerHTML.includes('openInfrastructure'))$('details').innerHTML+=`<div class="detail-actions"><button onclick="openInfrastructure(${id})">道路拓宽 / 铁路改造</button></div>`;}};
function upgradeQuote(k){let x=S.infrastructure[k];if(!x)return null;let a=S.cities[x.a],b=S.cities[x.b],r=requirements(a,b,x.type==='track'?'emu':'bus'),works=(r.bridge||0)+(r.tunnel||0),level=x.level;return {price:Math.ceil(Math.hypot(a.x-b.x,a.y-b.y)*(x.type==='track'?.8:level===0?.6:.9)+works*60),days:(x.type==='track'?5:level===0?2:3)+works,target:level+1};}
function openInfrastructure(id){let l=S.lines.find(l=>l.id===id);if(!l)return;if(l.type==='air')return toast('航空没有道路拓宽项目');let pairs=l.stops.slice(1).map((b,i)=>key(S.cities[l.stops[i]],S.cities[b],l.type));openModal(`<div class="modal-head"><h2>${escapeHTML(l.name)} · 路段升级</h2><button class="close" onclick="closeModal()">×</button></div><p>同一路段所有${l.type==='bus'?'公交':'动车与高铁'}共同受益。施工期间按升级前速度的70%通行。</p>${[...new Set(pairs)].map(k=>{let x=S.infrastructure[k],q=upgradeQuote(k);if(!x)return '';let done=x.level>=2,working=x.until>S.day;return `<div class="infra-card"><b>${escapeHTML(S.cities[x.a].name)} ↔ ${escapeHTML(S.cities[x.b].name)}</b><p>${x.type==='bus'?['普通道路','拓宽道路 +15%','快速道路 +30%'][x.level]:x.level===2?'高速铁路':'普通铁路 · 限速52'}</p>${working?`<span class="construction-label">施工中 · 还需 ${(x.until-S.day).toFixed(1)}天 · 速度−30%</span>`:done?'<small>已达最高等级</small>':`<button class="secondary" onclick="confirmUpgrade('${k}',${id})" ${S.points<q.price?'disabled':''}>升级 ¥${q.price} · 工期${q.days}天</button>`}</div>`;}).join('')}<p>动车在高速铁路上仍受自身速度限制；高铁在普通铁路上也需遵守路段限速。</p>`);}
function confirmUpgrade(k,id){let x=S.infrastructure[k],q=upgradeQuote(k);if(!x||x.until>S.day||x.level>=2)return;let affected=S.lines.filter(l=>l.stops.some((b,i)=>i&&key(S.cities[l.stops[i-1]],S.cities[b],l.type)===k));openModal(`<h2>确认施工</h2><p>${escapeHTML(S.cities[x.a].name)} ↔ ${escapeHTML(S.cities[x.b].name)}</p><div class="quote-row"><span>费用 / 工期</span><b>¥${q.price} / ${q.days}天</b></div><p>受影响线路：${affected.map(l=>escapeHTML(l.name)).join('、')}<br>开工扣费，期间速度−30%，完工后自动提速。施工不随撤线取消。</p><div class="construction-actions"><button onclick="openInfrastructure(${id})">返回</button><button class="primary" onclick="startUpgrade('${k}',${id})">开工</button></div>`);}
function startUpgrade(k,id){let x=S.infrastructure[k],q=upgradeQuote(k);if(!x||x.until>S.day||x.level>=2||S.points<q.price)return toast('无法开工，请检查资金或施工状态');spend(q.price,'construction',x.type==='bus'?'道路拓宽':'铁路改造');x.target=q.target;x.until=S.day+q.days;save();openInfrastructure(id);}
function drawInfrastructure(){for(let x of Object.values(S.infrastructure)){if(x.type==='air')continue;let a=S.cities[x.a],b=S.cities[x.b];if(!a||!b)continue;ctx.save();ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=x.type==='bus'?'#cbd1bf66':'#aebdb14d';ctx.lineWidth=x.type==='bus'?7+x.level*2:9;ctx.stroke();if(x.until>S.day){ctx.strokeStyle='#cd995d';ctx.lineWidth=2;ctx.setLineDash([5,9]);ctx.stroke();let mx=(a.x+b.x)/2,my=(a.y+b.y)/2;roundBody(mx-26,my-22,52,17,4,'#fff8e8','#d7be8e',.7);text('施工 '+Math.ceil(x.until-S.day)+'天',mx,my-10,8,'#a07842');}ctx.restore();}}
const CONCERTS={small:{name:'小型演唱会',cost:80,total:30,share:4,bonus:60,minSize:0},medium:{name:'城市音乐节',cost:200,total:70,share:5,bonus:100,minSize:1},large:{name:'区域巡演',cost:450,total:140,share:6,bonus:180,minSize:2}};
function concertAvailable(){return S.day>=12&&S.delivered>=8;}
function showOperations(){let ev=S.event,c=S.contract;openModal(`<div class="modal-head"><div><span class="eyebrow">OPERATIONS / 交通经营</span><h2>运营中心</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="ops-grid"><section class="infra-card"><h3>♫ 商演活动</h3>${ev?`<b>${escapeHTML(S.cities[ev.host].name)} · ${CONCERTS[ev.scale].name}</b><p>${concertPhase(ev)}<br>已出发 ${ev.spawned}/${ev.total} · 到场 ${ev.attended} · 返程 ${ev.returned}/${ev.attendees.length}<br>已获分成 ¥${ev.attended*ev.share} · 筹办支出 ¥${ev.cost}<br>预计时间：第${Math.floor(ev.arrivalStart)+1}天开始进场，第${Math.floor(ev.returnStart)+1}天返程，第${Math.floor(ev.end)+1}天结算。</p><button class="secondary" onclick="closeModal();openCity(${ev.host})">查看举办城市</button>`:`<p>选择举办城市，提前3天筹备。观众带音符，必须前往指定城市，散场后回到原客源城市。</p><button class="secondary" onclick="chooseConcert()" ${!concertAvailable()||S.day<S.eventCooldown?'disabled':''}>${!concertAvailable()?'第12天＋送达8人后开放':S.day<S.eventCooldown?'冷却中，还需'+Math.ceil(S.eventCooldown-S.day)+'天':'筹办演唱会'}</button>`}</section><section class="infra-card"><h3>公共服务合同</h3>${c?`<b>${escapeHTML(S.cities[c.city].name)}</b><p>剩余 ${(Math.max(0,c.end-S.day)).toFixed(1)}天<br>有效运输 ${c.count}/${c.goal} · 等待合格率 ${Math.round(c.count?c.good/c.count*100:0)}%<br>到期达到运输量且80%候车≤90秒：奖励 ¥${c.reward}。</p>`:`<p>为指定城市持续提供服务，在10天内完成运输量与等待要求。到期统一结算，未达标不扣款。</p><button class="secondary" onclick="chooseContract()" ${S.day<20||S.day<S.contractCooldown?'disabled':''}>${S.day<20?'第20天开放':S.day<S.contractCooldown?'合同冷却中':'选择服务城市'}</button>`}</section></div><div class="tabs"><button onclick="showTasks()">城市任务</button><button onclick="showFinance()">收支账本</button><button onclick="showEventHistory()">活动记录</button></div><p>普通乘客仍按颜色＋形状匹配。活动观众等待超时影响活动收益，不直接扣生命；普通乘客的等待压力仍需照顾。</p>`);}
function concertPhase(ev){return S.day<ev.arrivalStart?'筹备中，提前安排运力':S.day<ev.arrivalEnd?'观众进场中':S.day<ev.returnStart?'演出进行中':'散场返程中';}
function chooseConcert(){if(S.event||!concertAvailable()||S.day<S.eventCooldown)return;openModal(`<div class="modal-head"><h2>选择举办城市</h2><button class="close" onclick="showOperations()">×</button></div><p>同一时间一场活动。点击城市查看规模、费用与客源预测；确认后扣除筹办费。</p><div class="task-cities">${S.cities.filter(c=>!c.dormant).map(c=>`<section><h3>${escapeHTML(c.name)}</h3><p>${FEATURES[c.shape].name} · ${LEVELS[c.size]}<br>运营线路 ${cityLines(c.id).filter(l=>S.vehicles.some(v=>v.line===l.id)).length}条</p><button onclick="concertQuote(${c.id},'small')">选择这里 →</button></section>`).join('')}</div>`);}
function concertSources(host){return S.cities.filter(c=>c.id!==host&&!c.dormant);}
function concertQuote(host,scale){let c=S.cities[host],config=CONCERTS[scale];if(!c||c.dormant)return;let sources=concertSources(host),reachable=sources.filter(c=>plan(c.id,{origin:c.id,eventId:'preview',dest:host,color:S.cities[host].color,shape:S.cities[host].shape}));openModal(`<div class="modal-head"><h2>${escapeHTML(c.name)} · 商演筹办</h2><button class="close" onclick="chooseConcert()">×</button></div><div class="tabs">${Object.entries(CONCERTS).map(([k,x])=>`<button onclick="concertQuote(${host},'${k}')" ${c.size<x.minSize?'disabled':''} class="${k===scale?'selected':''}">${x.name}</button>`).join('')}</div><div class="finance-summary"><span>筹办费用<b>¥${config.cost}</b></span><span>计划观众<b>${config.total}人</b></span><span>每位到场分成<b>¥${config.share}</b></span></div><p>客源：${sources.map(c=>escapeHTML(c.name)).join('、')||'暂无'}。现有路网可达 ${reachable.length}/${sources.length}个客源城市。<br>3天筹备→6天进场→1天演出→6天返程。观众分批产生，不直接出现在举办城市。</p><p>实际到场才支付分成；至少70%到场、到场观众80%成功返程，可另获 ¥${config.bonus} 疏运奖金。交通票款另计，预计人数不保证收入。</p><div class="construction-actions"><button onclick="chooseConcert()">返回</button><button class="primary" onclick="startConcert(${host},'${scale}')" ${S.points<config.cost||sources.length<1||!cityLines(host).some(l=>S.vehicles.some(v=>v.line===l.id))?'disabled':''}>支付 ¥${config.cost} 并筹办</button></div>`);}
function startConcert(host,scale){let c=S.cities[host],x=CONCERTS[scale],sources=concertSources(host);if(S.event||!concertAvailable()||S.day<S.eventCooldown||!c||c.dormant||c.size<x.minSize||S.points<x.cost||!sources.length||!cityLines(host).some(l=>S.vehicles.some(v=>v.line===l.id)))return toast('当前不能筹办，请检查城市、线路或资金');spend(x.cost,'construction','筹办'+x.name);S.event={id:'concert-'+S.nextP+'-'+Math.floor(S.day*100),host,scale,cost:x.cost,total:x.total,share:x.share,bonus:x.bonus,created:S.day,arrivalStart:S.day+3,arrivalEnd:S.day+9,returnStart:S.day+10,end:S.day+16,sources:sources.map(c=>c.id),spawned:0,attended:0,returned:0,attendees:[],returnsSpawned:false};save();showOperations();toast('商演已筹办 · 3天准备运力，音符乘客指定举办城市');}
function eventPassenger(ev,origin,dest,returnTrip=false){let d=S.cities[dest];return {id:S.nextP++,origin,dest,eventId:ev.id,returnTrip,color:d.color,shape:d.shape,wait:0,ready:0,journey:0,legs:{}};}
function removeEventTravellers(ev,returnsOnly=false){let keep=p=>p.eventId!==ev.id||(returnsOnly?!p.returnTrip:p.returnTrip);for(let c of S.cities)c.q=c.q.filter(keep);for(let v of S.vehicles)v.people=v.people.filter(keep);}
function updateConcert(){let ev=S.event;if(!ev)return;if(S.day>=ev.arrivalStart&&S.day<ev.arrivalEnd){let desired=Math.min(ev.total,Math.floor(ev.total*(S.day-ev.arrivalStart)/(ev.arrivalEnd-ev.arrivalStart-1)));while(ev.spawned<desired){let origin=ev.sources[ev.spawned%ev.sources.length],source=S.cities[origin];if(source&&!source.dormant)source.q.push(eventPassenger(ev,origin,ev.host));ev.spawned++;}}if(S.day>=ev.arrivalEnd&&!ev.closedArrival){ev.closedArrival=true;removeEventTravellers(ev);toast('演出开始 · 实际到场 '+ev.attended+'人，准备散场接驳');}if(S.day>=ev.returnStart&&!ev.returnsSpawned){ev.returnsSpawned=true;for(let a of ev.attendees)S.cities[ev.host].q.push(eventPassenger(ev,ev.host,a.home,true));toast('演唱会散场 · '+ev.attendees.length+'位观众等待返程');}if(S.day>=ev.end){let bonus=ev.attended>=Math.ceil(ev.total*.7)&&ev.returned>=Math.ceil(ev.attended*.8)?ev.bonus:0;if(bonus)credit(bonus,'events','散场疏运奖金');removeEventTravellers(ev,true);S.eventArchive.unshift({host:ev.host,scale:ev.scale,attended:ev.attended,total:ev.total,returned:ev.returned,share:ev.share,cost:ev.cost,bonus,day:Math.floor(S.day)});S.eventArchive=S.eventArchive.slice(0,10);S.event=null;S.eventCooldown=S.day+10;toast('商演结算 · 到场'+ev.attended+'，返程'+ev.returned+' · 额外奖金 ¥'+bonus);save();}}
function showEventHistory(){openModal(`<div class="modal-head"><h2>商演记录</h2><button class="close" onclick="showOperations()">×</button></div>${S.eventArchive.map(e=>`<div class="infra-card"><b>${escapeHTML(S.cities[e.host].name)} · ${CONCERTS[e.scale].name}</b><p>到场 ${e.attended}/${e.total} · 返程 ${e.returned}/${e.attended}<br>分成与奖金 ¥${e.attended*e.share+e.bonus} − 筹办 ¥${e.cost}＝¥${e.attended*e.share+e.bonus-e.cost}（交通票款另计）</p></div>`).join('')||'<p>暂无已结束活动。</p>'}`);}
function chooseContract(){if(S.contract||S.day<20||S.day<S.contractCooldown)return;openModal(`<div class="modal-head"><h2>公共交通服务合同</h2><button class="close" onclick="showOperations()">×</button></div><p>10天内为指定城市完成出发或到达运输，至少80%候车不超过90秒。每次完整出行只计一次，演唱会乘客不计。合同未达标不扣款。</p><div class="task-cities">${S.cities.filter(c=>!c.dormant).map(c=>`<section><h3>${escapeHTML(c.name)}</h3><p>${contractGoal(c)}人 / 10天 · 奖金 ¥${100+c.size*60}</p><button onclick="acceptContract(${c.id})">承接服务</button></section>`).join('')}</div>`);}
function contractGoal(c){return Math.max(10,Math.ceil(passengerRate(c)*12*10*.9));}
function acceptContract(id){let c=S.cities[id];if(S.contract||S.day<20||S.day<S.contractCooldown||!c||c.dormant)return;S.contract={city:id,start:S.day,end:S.day+10,goal:contractGoal(c),reward:100+c.size*60,count:0,good:0};save();showOperations();}
function drawEventMarkers(){let ev=S.event;if(!ev)return;let c=S.cities[ev.host];roundBody(c.x-43,c.y-113-c.size*9,86,21,6,'#fff4e5','#d2ad76',.9);text('♪ '+(S.day<ev.arrivalStart?'筹备':S.day<ev.arrivalEnd?'进场':S.day<ev.returnStart?'演出':'返程'),c.x,c.y-99-c.size*9,10,'#a27145');}
showFinance=function(){let l=S.ledger;openModal(`<div class="modal-head"><h2>交通账本 · ¥${S.points}</h2><button class="close" onclick="closeModal()">×</button></div><div class="finance-summary">${[['初始资金',500],['交通票款',l.fares],['城市任务',l.tasks],['基础补助',l.subsidy],['商演收入',l.events],['服务合同',l.contracts],['建设 / 筹办',-l.construction],['车辆',-l.vehicles]].map(([a,b])=>`<span>${a}<b>${b>=0?'+':''}${b}</b></span>`).join('')}</div><p>起终点距离决定基础票款（1/2/3），有效路段按公交×1、动车×1.4、高铁×1.8、航空×3加权。到达后统一结算，重复路段不再计费，绕行不会增加基础票价；道路维护费月底结算，可查看预计支出。</p><div class="ledger-list">${S.history.map(e=>`<div class="quote-row"><span>第${e.day}天 · ${escapeHTML(e.label)}</span><b>${e.amount>0?'+':''}${e.amount}</b></div>`).join('')}</div><button class="secondary" onclick="showOperations()">运营中心</button>`);};
const oldUI=updateUI;updateUI=function(){oldUI();let ev=S.event;if(ev)$('notice').textContent='♪ '+S.cities[ev.host].name+' · '+concertPhase(ev)+' · 到场 '+ev.attended+'/'+ev.total;else if(S.infrastructure&&Object.values(S.infrastructure).some(x=>x.until>S.day))$('notice').textContent='道路施工中 · 受影响路段速度降低30%';};
const oldWelcome=welcome;welcome=function(hasSave){oldWelcome(hasSave);$('modal-content').innerHTML=$('modal-content').innerHTML.replace('测试版 0.1','测试版 0.4').replace('CITY & ECONOMY','TRANSPORT & OPERATIONS').replace('实际送达或完成通勤后计数，奖金自动到账。','累计、双向、限期和连续服务逐步变难。奖金自动到账。').replace('新城待接入，连通后再逐渐增加客流。','普通乘客按颜色＋形状匹配；商演观众带音符、指定城市。').replace('每个游戏日12秒，可暂停、调速。','每个游戏日12秒，可暂停、调速。运营中心可筹办商演、接合同；线路详情可升级道路。<br>0.4采用独立新存档，0.1存档仍保留。');};
help=function(){openModal(`<div class="modal-head"><h2>0.4 测试手册</h2><button class="close" onclick="closeModal()">×</button></div><div class="help-grid"><div><p><b>拉线和目的地</b><br>原有拖动操作不变。乘客小方块内的形状＋颜色对应目的地，同色同形城市均可接收。点击候车列表标记匹配城市。音符观众指定举办城市或返程城市。</p><p><b>城市任务更难</b><br>累计20人→出发/到达各12人→12天滚动高效运输→连续3天→实际到达2类别→连续5天。连续考核要求真实运输和80%等待合格率；失败只重置连续天数。每两项前期任务升级城市。</p><p><b>道路与铁路</b><br>点击线路→道路拓宽/铁路改造。道路完工速度+15%/+30%，施工按当前速度70%通行。桥隧增加费用和工期。同路段各线共享，道路与铁路分开。普通铁路限速52，高速铁路允许高铁发挥速度。</p></div><div><p><b>资金与车辆</b><br>开局500，公交180；动车560，高铁900，航空1600。按有效运输方式加权票价，终点统一结算，重复路段不重复计费。十天补助100，无免费车辆、无每日运营费。</p><p><b>商演与合同</b><br>运营中心选城、选规模，先扣筹办费。3天筹备、6天进场、1天演出、6天返程。实际到场才有分成，良好疏运有奖金。观众超时不直接扣命，普通旅客仍有等待压力。第20天可接10天服务合同。</p><p><b>阶段开放</b><br>动车：25天＋60送达；高铁：65天＋250送达＋3座小城；航空：120天＋600送达。可提前查看价格储蓄。购物、编辑、运营总览暂停计时。</p></div></div><div class="construction-actions"><button onclick="showOperations()">运营中心</button><button class="danger" onclick="if(confirm('重新开始0.4测试？'))newGame()">重新测试</button><a href="../">返回正式版</a></div>`);};
$('operations').onclick=showOperations;

